using System;
using System.Collections;
using LittleLeo;
using LittleLeo.Events;
using NaughtyAttributes;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "VengefulStabEffect", menuName = "Data/Battle/Effects/Enemy/VengefulStab Effect")]
public class VengefulStabEffect : Effect
{
	[Header("Vengeful Stab")]
	[SerializeField]
	private float vengefulStabSFXDelay;

	[SerializeField]
	private bool vengefulStab;

	[Header("Meissa Battle")]
	[SerializeField]
	private bool uncontrollableMeissa;

	[SerializeField]
	[ShowIf("uncontrollableMeissa")]
	private BoolEvent OnMeissaPurifiedByPlayer;

	[SerializeField]
	private bool saiphsHelp;

	[NonSerialized]
	private bool alreadyActivated;

	[NonSerialized]
	private int startingAmount;

	[NonSerialized]
	private bool defeatAlreadyComputed;

	private UnitEffects unitEffects;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		string text = GetLocalizedDescription();
		if (amount == EffectsValues.NO_VALUE || amount == -1)
		{
			string[] list = text.Split('\n');
			return GetEffectDescriptionWithAmountReplacedWithX(list.First(), GetNumberToReplaceWithX(), null);
		}
		if (uncontrollableMeissa)
		{
			text = text + "\n" + base.localizationManager.GetLocalizedString("UncontrollableMeissa_D2");
		}
		return Smart.Format(text, startingAmount, amount);
	}

	public override void Initialize(int effectAmount, GameObject effectOwner, GameObject source)
	{
		alreadyActivated = false;
		startingAmount = effectAmount;
		unitEffects = effectOwner.GetComponent<UnitEffects>();
		if (uncontrollableMeissa)
		{
			defeatAlreadyComputed = false;
		}
	}

	public override int ActivateEffectWithSource(int effectAmount, GameObject effectOwner, GameObject source)
	{
		if (saiphsHelp)
		{
			if (alreadyActivated)
			{
				return effectAmount;
			}
		}
		else if (!ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) || alreadyActivated)
		{
			return effectAmount;
		}
		UnitEffects component = effectOwner.GetComponent<UnitEffects>();
		int num = effectAmount - 1;
		if (num == 0)
		{
			alreadyActivated = true;
			component.IsEffectActiveGetEffectInstance(this).StopBlinkingFeedback(shouldForce: true);
			component.RemoveEffect(this, activateFeedback: false);
			component.IsEffectActive(this);
			CorruptedAnimalActivation component2 = effectOwner.GetComponent<CorruptedAnimalActivation>();
			ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(BasicDiceActivation(effectOwner, basic: true));
			if (component2.IsBoosted)
			{
				ReferenceSingleton<GameStateManager>.Instance.ActionsQueueState.EnqueueAction(BasicDiceActivation(effectOwner, basic: false));
			}
			ReferenceSingleton<GameStateManager>.Instance.SetActionsQueueState();
		}
		else
		{
			component.IsEffectActiveAndDecreaseEffect(this, 1);
		}
		if (num == 1)
		{
			component.IsEffectActiveGetEffectInstance(this).PlayBlinkingFeedback();
		}
		return effectAmount;
	}

	private IEnumerator BasicDiceActivation(GameObject effectOwner, bool basic)
	{
		if (effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			yield break;
		}
		CorruptedAnimalActivation ca = effectOwner.GetComponent<CorruptedAnimalActivation>();
		yield return new WaitForSeconds(0.2f);
		if (vengefulStab)
		{
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, vengefulStabSFXDelay, delegate
			{
				PlayEffectActivationSFX();
			});
		}
		AnimationType animationType = (vengefulStab ? AnimationType.Skill : AnimationType.Attack);
		if (basic)
		{
			yield return ca.BasicDiceActivation(animationType);
		}
		else
		{
			yield return ca.BoostDiceActivation(animationType);
		}
		yield return InvokeAlternatives.WaitForFrames(3);
		alreadyActivated = false;
	}

	public override void RemoveEffect(int effectAmount, GameObject effectOwner)
	{
		if (!effectOwner.GetComponent<CorruptionStats>().IsDefeated())
		{
			effectOwner.GetComponent<UnitEffects>().AddEffect(this, startingAmount, effectFeedback: true, callEffectsCallbacks: false);
		}
	}

	public void MeissaPurified(GameObject source, CorruptedAnimalCorruptionStats corruptedAnimalCorruptionStats)
	{
		if (defeatAlreadyComputed)
		{
			return;
		}
		InvokeAlternatives.InvokeAfterMultipleFrames(ReferenceSingleton<CoroutineHandler>.Instance, ReferenceSingleton<BattleHandler>.Instance.FramesToWaitToUpdateCorruption + 2, delegate
		{
			if (corruptedAnimalCorruptionStats.IsDefeated())
			{
				defeatAlreadyComputed = true;
				OnMeissaPurifiedByPlayer.Raise(source == null || ReferenceSingleton<BattleHandler>.Instance.IsSourcePlayer(source) || ReferenceSingleton<BattleHandler>.Instance.IsSourceCompanions(source));
			}
		});
	}
}
